<?php require __DIR__."/vendor/autoload.php"; $app = require_once __DIR__."/bootstrap/app.php"; $app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap(); $req = Illuminate\Http\Request::create("/api/poa/fichas", "GET", ["ejercicio_id"=>2026, "area_id"=>"todas"]); $res = app()->handle($req); $json = json_decode($res->getContent(), true); if (isset($json["message"])) { echo "Error: ".$json["message"]."\n"; echo $json["file"].":".$json["line"]."\n"; } else { echo count($json). " proyectos.\n"; }
